// ============================================================================
// TASK A: GUI IMAGE VIEWER IMPLEMENTATION
// ============================================================================

bool gui_trigger_jpeg_conversion(const char* jpeg_path) {
    if (!jpeg_path || !jpeg_path[0]) {
        printf("[GUI] ERROR: No JPEG path specified\n");
        return false;
    }
    
    printf("[GUI] Starting JPEG conversion: %s\n", jpeg_path);
    printf("[GUI] Freezing current state and switching to converter...\n");
    
    // Switch to JPEG converter task
    // The task switcher will automatically freeze this task's RAM
    bool result = task_switch_to(JPEG_CONVERTER_KERNEL);
    
    if (!result) {
        TaskSwitcherError err = task_switcher_get_error();
        printf("[GUI] ERROR: Failed to switch to converter: %s\n", 
               task_switcher_error_to_string(err));
        return false;
    }
    
    // In real implementation, this function would not return
    // The new task (JPEG converter) would be running
    // When the user clicks "Back" in the converter, task_restore() is called
    // and execution returns here
    
    printf("[GUI] Resumed after conversion\n");
    return true;
}

uint32_t gui_load_conversion_result(RgbImageHeader* header, 
                                   uint8_t* rgb_buffer, 
                                   uint32_t buffer_size) {
    if (!header || !rgb_buffer || buffer_size == 0) {
        printf("[GUI] ERROR: Invalid parameters\n");
        return 0;
    }
    
    // Check if conversion was completed
    if (!task_child_has_file("converted.rgb")) {
        printf("[GUI] No conversion result found\n");
        return 0;
    }
    
    printf("[GUI] Loading conversion result...\n");
    
    // Load header
    uint32_t header_size = sizeof(RgbImageHeader);
    uint32_t bytes_read = task_load_from_child("converted.hdr", 
                                                (void*)header, 
                                                header_size);
    
    if (bytes_read != header_size) {
        printf("[GUI] ERROR: Failed to load header\n");
        return 0;
    }
    
    // Validate header
    if (header->bits_per_pixel != 24) {
        printf("[GUI] ERROR: Unsupported BPP: %u\n", header->bits_per_pixel);
        return 0;
    }
    
    // Load RGB data
    uint32_t data_to_read = (header->data_size < buffer_size) ? 
                            header->data_size : buffer_size;
    
    bytes_read = task_load_from_child("converted.rgb", 
                                     (void*)rgb_buffer, 
                                     data_to_read);
    
    if (bytes_read == 0) {
        printf("[GUI] ERROR: Failed to load RGB data\n");
        return 0;
    }
    
    // Verify CRC32 if needed
    if (header->crc32 != 0) {
        uint32_t calculated_crc = crc32(0xFFFFFFFF, rgb_buffer, bytes_read) ^ 0xFFFFFFFF;
        if (calculated_crc != header->crc32) {
            printf("[GUI] WARNING: CRC32 mismatch! (expected %08lX, got %08lX)\n", 
                   header->crc32, calculated_crc);
        }
    }
    
    printf("[GUI] Loaded %u bytes of RGB data (%ux%u, %u bpp)\n", 
           bytes_read, header->width, header->height, header->bits_per_pixel);
    
    return bytes_read;
}

