// ============================================================================
// TASK B: JPEG CONVERTER IMPLEMENTATION
// ============================================================================

bool jpeg_converter_run(const char* jpeg_path) {
    if (!jpeg_path || !jpeg_path[0]) {
        printf("[CONVERTER] ERROR: No JPEG path specified\n");
        return false;
    }
    
    printf("[CONVERTER] Starting JPEG to RGB conversion\n");
    printf("[CONVERTER] Input: %s\n", jpeg_path);
    printf("[CONVERTER] Output: %s\n", JPEG_OUTPUT_FILE);
    
    // Perform conversion
    bool result = jpeg_to_rgb_convert(jpeg_path, 
                                      JPEG_OUTPUT_FILE,
                                      "/tmp/converted.hdr");
    
    if (result) {
        printf("[CONVERTER] Conversion complete!\n");
        
        // Create a flag file to indicate completion
        const char* flag = "DONE";
        task_save_for_parent("conversion_done.flag", (const void*)flag, 4);
        
        printf("[CONVERTER] Saved results. Ready to return to GUI.\n");
        printf("[CONVERTER] User should click 'Back' to return.\n");
    } else {
        printf("[CONVERTER] ERROR: Conversion failed\n");
    }
    
    return result;
}

bool jpeg_to_rgb_convert(const char* jpeg_path, 
                        const char* rgb_path, 
                        const char* header_path) {
    // In a real implementation, this would use a JPEG decoder library
    // For example: TinyJPEG, JPEGLIB, or platform-specific decoder
    
    // This is a MOCK implementation that demonstrates the pattern
    
    printf("[CONVERTER] Decoding JPEG: %s\n", jpeg_path);
    
    // Simulate JPEG decoding
    // In real code:
    // 1. Open JPEG file from SD card
    // 2. Decode to RGB
    // 3. Get width, height, data
    
    // MOCK: Create a dummy RGB image
    uint16_t width = 800;
    uint16_t height = 600;
    uint8_t bpp = 24;  // RGB888
    uint32_t data_size = width * height * (bpp / 8);
    
    printf("[CONVERTER] Image: %ux%u, %u bpp\n", width, height, bpp);
    printf("[CONVERTER] RGB data size: %u bytes\n", data_size);
    
    // Allocate and fill with test pattern (in real code, this is actual RGB data)
    uint8_t* rgb_data = (uint8_t*)malloc(data_size);
    if (!rgb_data) {
        printf("[CONVERTER] ERROR: Failed to allocate RGB buffer\n");
        return false;
    }
    
    // Fill with gradient pattern for demo
    for (uint32_t i = 0; i < data_size; i += 3) {
        rgb_data[i] = (uint8_t)(i % 256);     // R
        rgb_data[i+1] = (uint8_t)((i/2) % 256); // G  
        rgb_data[i+2] = (uint8_t)((i/3) % 256); // B
    }
    
    // Create header
    RgbImageHeader header;
    header.width = width;
    header.height = height;
    header.bits_per_pixel = bpp;
    header.data_size = data_size;
    header.crc32 = crc32(0xFFFFFFFF, rgb_data, data_size) ^ 0xFFFFFFFF;
    
    printf("[CONVERTER] CRC32: %08lX\n", header.crc32);
    
    // Save header
    if (!task_save_for_parent("converted.hdr", (const void*)&header, sizeof(header))) {
        printf("[CONVERTER] ERROR: Failed to save header\n");
        free(rgb_data);
        return false;
    }
    
    // Save RGB data
    if (!task_save_for_parent("converted.rgb", (const void*)rgb_data, data_size)) {
        printf("[CONVERTER] ERROR: Failed to save RGB data\n");
        free(rgb_data);
        return false;
    }
    
    free(rgb_data);
    printf("[CONVERTER] Successfully saved RGB data\n");
    
    return true;
}

