/// @brief Example: Back button handler that calls task_restore()
/// 
/// This would be called from your GUI event loop when user clicks "Back"
void handle_back_button(void) {
    if (task_has_frozen_parent()) {
        printf("[GUI] Back button pressed, restoring parent task...\n");
        bool result = task_restore();
        if (!result) {
            printf("[GUI] ERROR: Failed to restore: %s\n", 
                   task_switcher_error_to_string(task_switcher_get_error()));
        }
    } else {
        printf("[GUI] No parent task to restore\n");
    }
}

/// @brief Example: Main loop that checks for conversion results
void gui_main_loop(void) {
    // Check if we just returned from a child task
    if (task_has_frozen_parent()) {
        // We are the child task (converter)
        // Run converter and wait for back button
        jpeg_converter_run(JPEG_INPUT_FILE);
        
        // In real code, you'd have an event loop here
        // while (1) {
        //     check_input();
        //     if (back_button_pressed) {
        //         task_restore();
        //     }
        // }
    } else {
        // We are the parent task (GUI)
        // Check for conversion results
        RgbImageHeader header;
        uint8_t rgb_buffer[1024 * 100];  // Small buffer for demo
        uint32_t loaded = gui_load_conversion_result(&header, rgb_buffer, sizeof(rgb_buffer));
        
        if (loaded > 0) {
            printf("[GUI] Displaying converted image...\n");
            // display_image(&header, rgb_buffer);
            gui_cleanup_conversion();
        }
    }
}
